// ----------------------
// NORMALIZADOR
// ----------------------
function normalizar(texto) {
  return (texto || "")
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

// ----------------------
// MAPEO DE CIUDADES → ID
// ----------------------
const ciudadesMap = {
  "santa cruz": 1,
  // "beni": 2,
  // "chuquisaca": 9,
  "cochabamba": 4,
  "la paz": 5,
  // "oruro": 6,
  // "pando": 5,
  "potosi": 8,
  "tarija": 9,
  "todas": 10
};

const TODAS_ID = 10;

// ----------------------
// INPUT CIUDAD
// ----------------------
let ciudadRaw = $('When Executed by Another Workflow').first().json.ciudad || "";
let ciudadNormalizada = normalizar(ciudadRaw);
let ciudadId = ciudadesMap[ciudadNormalizada] ?? TODAS_ID;

// ----------------------
// DATA
// ----------------------
let items = $input.first()?.json?.data || [];
if (!Array.isArray(items)) items = [];

// ----------------------
// PARSER DE CIUDAD (soporta "3", "1,5,4,8", 10, etc.)
// ----------------------
function parsearCiudades(valor) {
  if (valor === null || valor === undefined || valor === "") return [];
  return String(valor)
    .split(",")
    .map(v => Number(v.trim()))
    .filter(n => !isNaN(n));
}

// ----------------------
// PARSER DE JSON SEGURO
// ----------------------
function parseJsonSeguro(valor) {
  if (!valor || valor === "" || valor === "[]" || valor === "null") return [];
  if (Array.isArray(valor)) return valor;
  try {
    const parsed = JSON.parse(valor);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

// ----------------------
// FILTRO
// ----------------------
let filtrados = items.filter(prod => {
  const ciudadesProd = parsearCiudades(prod.ciudad_producto_sucursal);
  const productType = Number(prod.product_type);

  const matchCiudad = ciudadesProd.includes(ciudadId) || ciudadesProd.includes(TODAS_ID);
  const matchType = productType === 10;

  return matchCiudad && matchType;
});

// ----------------------
// PARSEAR combos_productos + ELIMINAR created_at / updated_at
// ----------------------
filtrados = filtrados.map(({ created_at, updated_at, ...prod }) => ({
  ...prod,
  combos_productos: parseJsonSeguro(prod.combos_productos),
  combos_productos_cantidad: parseJsonSeguro(prod.combos_productos_cantidad)
}));

// ----------------------
// ELIMINAR DUPLICADOS (por prod.id)
// ----------------------
let uniqueMap = new Map();
filtrados.forEach(prod => {
  if (!uniqueMap.has(prod.id)) {
    uniqueMap.set(prod.id, prod);
  }
});
let resultado = Array.from(uniqueMap.values());

// ----------------------
// OUTPUT
// ----------------------
return [
  {
    json: {
      ciudad_input: ciudadRaw,
      ciudad_normalizada: ciudadNormalizada,
      ciudad_id: ciudadId,
      total_productos: resultado.length,
      data: resultado
    }
  }
];
